# if-else
score <- 85

if (score >= 90) {
    grade <- "A"
} else if (score >= 80) {
    grade <- "B"
} else if (score >= 70) {
    grade <- "C"
} else {
    grade <- "F"
}

# ifelse (벡터화)
scores <- c(95, 75, 88, 62)
grades <- ifelse(scores >= 80, "Pass", "Fail")

# for 루프
for (i in 1:5) {
    print(i)
}

fruits <- c("apple", "banana", "cherry")
for (fruit in fruits) {
    print(fruit)
}

# while 루프
count <- 0
while (count < 5) {
    print(count)
    count <- count + 1
}

# repeat (무한 루프)
count <- 0
repeat {
    print(count)
    count <- count + 1
    if (count >= 5) break
}

# next (continue)
for (i in 1:10) {
    if (i %% 2 == 0) next
    print(i)  # 홀수만 출력
}
